    // dst: [$vapor]
    //
    TwistExpander_Polaris_Arx::KEY_A_A_D(PARAMS_SEED);

    KeyDiffuse_B_A_A(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Polaris_Arx::KEY_A_A_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(POLARIS_KEY_A_A_IceLaneA, POLARIS_KEY_A_A_IceLaneB, POLARIS_KEY_A_A_IceLaneC, POLARIS_KEY_A_A_IceLaneD, &(pWorkSpace->mKeyBoxA[0U][0]));

    // Key flow — A / B

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Polaris_Arx::KEY_A_B_A(PARAMS_SEED);

