    // dst: [$water]
    //
    TwistExpander_Polaris_Arx::KEY_A_B_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Polaris_Arx::KEY_A_B_D(PARAMS_SEED);

    KeyDiffuse_B_A_B(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Polaris_Arx::KEY_A_B_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(POLARIS_KEY_A_B_IceLaneA, POLARIS_KEY_A_B_IceLaneB, POLARIS_KEY_A_B_IceLaneC, POLARIS_KEY_A_B_IceLaneD, &(pWorkSpace->mKeyBoxA[1U][0]));

    // Key flow — A / C

