void TwistExpander_Polaris::TwistBlock(TwistWorkSpace *pWorkSpace,
                                       std::uint8_t *pSource,
                                       std::uint8_t *pCrossLaneA,
                                       std::uint8_t *pCrossLaneB,
                                       std::uint8_t *pCrossLaneC,
                                       std::uint8_t *pCrossLaneD,
                                       std::uint8_t *pDestination,
                                       bool pStifleKey,
                                       MUTABLE_PARAMS) {
    if ((pWorkSpace == nullptr) || (pSource == nullptr) ||
        (pCrossLaneA == nullptr) || (pCrossLaneB == nullptr) ||
        (pCrossLaneC == nullptr) || (pCrossLaneD == nullptr) ||
        (pDestination == nullptr) || MUTABLE_PARAMS_ARE_NULL) { return; }
    std::uint8_t *aEarthLaneA = pWorkSpace->mEarthLaneA;
    std::uint8_t *aEarthLaneB = pWorkSpace->mEarthLaneB;
    std::uint8_t *aEarthLaneC = pWorkSpace->mEarthLaneC;
    std::uint8_t *aEarthLaneD = pWorkSpace->mEarthLaneD;
    std::uint8_t *aAetherLaneA = pWorkSpace->mAetherLaneA;
    std::uint8_t *aAetherLaneB = pWorkSpace->mAetherLaneB;
    std::uint8_t *aAetherLaneC = pWorkSpace->mAetherLaneC;
    std::uint8_t *aAetherLaneD = pWorkSpace->mAetherLaneD;
    std::uint8_t *aLunarLaneA = pWorkSpace->mLunarLaneA;
    std::uint8_t *aLunarLaneB = pWorkSpace->mLunarLaneB;
    std::uint8_t *aLunarLaneC = pWorkSpace->mLunarLaneC;
    std::uint8_t *aLunarLaneD = pWorkSpace->mLunarLaneD;
    std::size_t *aIndexList256A = pWorkSpace->mIndexList256A;
    std::size_t *aIndexList256B = pWorkSpace->mIndexList256B;
    std::size_t *aIndexList256C = pWorkSpace->mIndexList256C;
    std::size_t *aIndexList256D = pWorkSpace->mIndexList256D;

    std::uint64_t aIngress = *pIngress + 0x37B2B2DA27B56B63ULL;
    std::uint64_t aCarry = *pCarry + 0xF40BEC33821050C1ULL;
    std::uint64_t aWandererA = *pWandererA + 0xEA882BD8B727E585ULL;
    std::uint64_t aWandererB = *pWandererB + 0xCA256E406918CC92ULL;
    std::uint64_t aWandererC = *pWandererC + 0x7672F799A05FB6EFULL;
    std::uint64_t aWandererD = *pWandererD + 0xA4C541523ACC7478ULL;
    std::uint64_t aWandererE = *pWandererE + 0x69812E480CCA5F18ULL;
    std::uint64_t aWandererF = *pWandererF + 0xB7B609CFBD372F45ULL;
    std::uint64_t aWandererG = *pWandererG + 0x17039CD861511E98ULL;
    std::uint64_t aWandererH = *pWandererH + 0xDA634EA5BC7C1B74ULL;
    std::uint64_t aWandererI = *pWandererI + 0x57289B763951CC8EULL;
    std::uint64_t aWandererJ = *pWandererJ + 0x491454B79574899BULL;
    std::uint64_t aWandererK = *pWandererK + 0x1D17BF3FAAC86897ULL;

    ////////////////////////////////////////////////////////
    //
    // Main twist loops
    //
    // src: [source, key_read_a, key_read_b]
    // dst: [$aether]
    //
    TwistExpander_Polaris_Arx::TWIST_A(PARAMS_TWIST);

    //
    // src: [$aether]
    // dst: [$lunar]
    //
    TwistExpander_Polaris_Arx::TWIST_B(PARAMS_TWIST);

    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixSelectB;

    std::uint8_t aDomainWordMatrixUnrollA = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixUnrollA;
    std::uint8_t aDomainWordMatrixUnrollB = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixUnrollB;

    std::uint8_t aDomainWordMatrixArgA = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixArgA;
    std::uint8_t aDomainWordMatrixArgB = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixArgB;
    std::uint8_t aDomainWordMatrixArgC = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixArgC;
    std::uint8_t aDomainWordMatrixArgD = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixArgD;

    TwistDiffuse::DiffuseWithDomainWords(
        aLunarLaneA, aLunarLaneB, aLunarLaneC, aLunarLaneD,  // input lanes
        aEarthLaneA, aEarthLaneB, aEarthLaneC, aEarthLaneD, // output lanes
        aAetherLaneA, aAetherLaneB, aAetherLaneC, aAetherLaneD, // entropy lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D, &mMatrix, aDomainWordMatrixSelectA, aDomainWordMatrixSelectB, aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB, aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$earth]
    // dst: [$crystal]
    //
    TwistExpander_Polaris_Arx::TWIST_C(PARAMS_TWIST);
    //
    ////////////////////////////////////////////////////////

    ////////////////////////////////////////////////////////
    //
    // Folding main twist loops into destination
    //
    TwistSquash::SquashA(pWorkSpace->mCrystalLaneA, pWorkSpace->mCrystalLaneB, pWorkSpace->mCrystalLaneC, pWorkSpace->mCrystalLaneD, pDestination);
    //
    ////////////////////////////////////////////////////////

    *pIngress = aIngress;
    *pCarry = aCarry;
    *pWandererA = aWandererA;
    *pWandererB = aWandererB;
    *pWandererC = aWandererC;
    *pWandererD = aWandererD;
    *pWandererE = aWandererE;
    *pWandererF = aWandererF;
    *pWandererG = aWandererG;
    *pWandererH = aWandererH;
    *pWandererI = aWandererI;
    *pWandererJ = aWandererJ;
    *pWandererK = aWandererK;

    ////////////////////////////////////////////////////////
    //
    // Key box management
    //
    if (pStifleKey == true) {
        TwistShiftBox::ShiftKeyBoxA(pWorkSpace);
        TwistShiftBox::ShiftKeyBoxB(pWorkSpace);
    } else {
        TwistForkKeyHalfA(pWorkSpace);
        TwistForkKeyHalfB(pWorkSpace);
        
        GrowKeyA(pWorkSpace, pCrossLaneA, pCrossLaneC, ARX_STATE_VARS);
        
        aIngress = *pIngress;
        aCarry = *pCarry;
        aWandererA = *pWandererA;
        aWandererB = *pWandererB;
        aWandererC = *pWandererC;
        aWandererD = *pWandererD;
        aWandererE = *pWandererE;
        aWandererF = *pWandererF;
        aWandererG = *pWandererG;
        aWandererH = *pWandererH;
        aWandererI = *pWandererI;
        aWandererJ = *pWandererJ;
        aWandererK = *pWandererK;
        
        GrowKeyB(pWorkSpace, pCrossLaneB, pCrossLaneD, ARX_STATE_VARS);
        
    }
    //
    ////////////////////////////////////////////////////////
}

void TwistExpander_Polaris::GrowKeyA(TwistWorkSpace *pWorkSpace,
                  std::uint8_t *pCrossLaneA,
                  std::uint8_t *pCrossLaneB,
                  MUTABLE_PARAMS) {
    //
    // src: [$spirit, cross_a, cross_b]
    // dst: [$arcane]
    //
    TwistExpander_Polaris_Arx::GROW_A_A(PARAMS_GROW);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Polaris_Arx::GROW_A_B(PARAMS_GROW);

    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mKeyRotateAConstants.mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pWorkSpace->mDomainBundle.mKeyRotateAConstants.mMatrixSelectB;
    std::uint8_t aDomainWordMatrixUnrollA = pWorkSpace->mDomainBundle.mKeyRotateAConstants.mMatrixUnrollA;
    std::uint8_t aDomainWordMatrixUnrollB = pWorkSpace->mDomainBundle.mKeyRotateAConstants.mMatrixUnrollB;
    std::uint8_t aDomainWordMatrixArgA = pWorkSpace->mDomainBundle.mKeyRotateAConstants.mMatrixArgA;
    std::uint8_t aDomainWordMatrixArgB = pWorkSpace->mDomainBundle.mKeyRotateAConstants.mMatrixArgB;
    std::uint8_t aDomainWordMatrixArgC = pWorkSpace->mDomainBundle.mKeyRotateAConstants.mMatrixArgC;
    std::uint8_t aDomainWordMatrixArgD = pWorkSpace->mDomainBundle.mKeyRotateAConstants.mMatrixArgD;

    TwistDiffuse::KeyDiffuseWithDomainWordsA(
        pWorkSpace->mPlasmaLaneA,
        pWorkSpace->mPlasmaLaneB,
        pWorkSpace->mPlasmaLaneC,
        pWorkSpace->mPlasmaLaneD,
        pWorkSpace->mRainbowLaneA,
        pWorkSpace->mRainbowLaneB,
        pWorkSpace->mRainbowLaneC,
        pWorkSpace->mRainbowLaneD,
        pWorkSpace->mArcaneLaneA,
        pWorkSpace->mArcaneLaneB,
        pWorkSpace->mArcaneLaneC,
        pWorkSpace->mArcaneLaneD,
        pWorkSpace->mIndexList256A, pWorkSpace->mIndexList256B,
        pWorkSpace->mIndexList256C, pWorkSpace->mIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB,
        aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Polaris_Arx::GROW_A_C(PARAMS_GROW);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Polaris_Arx::GROW_A_D(PARAMS_GROW);

    TwistDiffuse::KeyDiffuseWithDomainWordsA(
        pWorkSpace->mVaporLaneA,
        pWorkSpace->mVaporLaneB,
        pWorkSpace->mVaporLaneC,
        pWorkSpace->mVaporLaneD,
        pWorkSpace->mFrostLaneA,
        pWorkSpace->mFrostLaneB,
        pWorkSpace->mFrostLaneC,
        pWorkSpace->mFrostLaneD,
        pWorkSpace->mWaterLaneA,
        pWorkSpace->mWaterLaneB,
        pWorkSpace->mWaterLaneC,
        pWorkSpace->mWaterLaneD,
        pWorkSpace->mIndexList256A, pWorkSpace->mIndexList256B,
        pWorkSpace->mIndexList256C, pWorkSpace->mIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB,
        aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Polaris_Arx::GROW_A_E(PARAMS_GROW);

    TwistShiftBox::ShiftKeyBoxA(pWorkSpace);
    TwistSquash::SquashKeyA(
        pWorkSpace->mIceLaneA,
        pWorkSpace->mIceLaneB,
        pWorkSpace->mIceLaneC,
        pWorkSpace->mIceLaneD,
        &(pWorkSpace->mKeyBoxA[0][0]));
}

void TwistExpander_Polaris::GrowKeyB(TwistWorkSpace *pWorkSpace,
                  std::uint8_t *pCrossLaneA,
                  std::uint8_t *pCrossLaneB,
                  MUTABLE_PARAMS) {
    //
    // src: [$divination, cross_a, cross_b]
    // dst: [$arcane]
    //
    TwistExpander_Polaris_Arx::GROW_B_A(PARAMS_GROW);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Polaris_Arx::GROW_B_B(PARAMS_GROW);

    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mMatrixSelectB;
    std::uint8_t aDomainWordMatrixUnrollA = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mMatrixUnrollA;
    std::uint8_t aDomainWordMatrixUnrollB = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mMatrixUnrollB;
    std::uint8_t aDomainWordMatrixArgA = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mMatrixArgA;
    std::uint8_t aDomainWordMatrixArgB = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mMatrixArgB;
    std::uint8_t aDomainWordMatrixArgC = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mMatrixArgC;
    std::uint8_t aDomainWordMatrixArgD = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mMatrixArgD;

    TwistDiffuse::KeyDiffuseWithDomainWordsB(
        pWorkSpace->mPlasmaLaneA,
        pWorkSpace->mPlasmaLaneB,
        pWorkSpace->mPlasmaLaneC,
        pWorkSpace->mPlasmaLaneD,
        pWorkSpace->mRainbowLaneA,
        pWorkSpace->mRainbowLaneB,
        pWorkSpace->mRainbowLaneC,
        pWorkSpace->mRainbowLaneD,
        pWorkSpace->mArcaneLaneA,
        pWorkSpace->mArcaneLaneB,
        pWorkSpace->mArcaneLaneC,
        pWorkSpace->mArcaneLaneD,
        pWorkSpace->mIndexList256A, pWorkSpace->mIndexList256B,
        pWorkSpace->mIndexList256C, pWorkSpace->mIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB,
        aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Polaris_Arx::GROW_B_C(PARAMS_GROW);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Polaris_Arx::GROW_B_D(PARAMS_GROW);

    TwistDiffuse::KeyDiffuseWithDomainWordsB(
        pWorkSpace->mVaporLaneA,
        pWorkSpace->mVaporLaneB,
        pWorkSpace->mVaporLaneC,
        pWorkSpace->mVaporLaneD,
        pWorkSpace->mFrostLaneA,
        pWorkSpace->mFrostLaneB,
        pWorkSpace->mFrostLaneC,
        pWorkSpace->mFrostLaneD,
        pWorkSpace->mWaterLaneA,
        pWorkSpace->mWaterLaneB,
        pWorkSpace->mWaterLaneC,
        pWorkSpace->mWaterLaneD,
        pWorkSpace->mIndexList256A, pWorkSpace->mIndexList256B,
        pWorkSpace->mIndexList256C, pWorkSpace->mIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB,
        aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Polaris_Arx::GROW_B_E(PARAMS_GROW);

    TwistShiftBox::ShiftKeyBoxB(pWorkSpace);
    TwistSquash::SquashKeyA(
        pWorkSpace->mIceLaneA + (W_KEY * 1U),
        pWorkSpace->mIceLaneB + (W_KEY * 1U),
        pWorkSpace->mIceLaneC + (W_KEY * 1U),
        pWorkSpace->mIceLaneD + (W_KEY * 1U),
        &(pWorkSpace->mKeyBoxB[0][0]));
}

void TwistExpander_Polaris::TwistForkKeyHalfA(TwistWorkSpace *pWorkSpace) {
    static_assert(S_BLOCK == 32768, "Twist fork source size changed.");
    static_assert(S_HALF == 16384, "Twist fork half size changed.");
    static_assert(W_KEY == 2048, "Twist fork key size changed.");

    std::uint8_t *aSourceLaneA = pWorkSpace->mCrystalLaneA;
    std::uint8_t *aSourceLaneB = pWorkSpace->mCrystalLaneB;
    std::uint8_t *aSourceLaneC = pWorkSpace->mCrystalLaneC;
    std::uint8_t *aSourceLaneD = pWorkSpace->mCrystalLaneD;

    std::uint8_t *aStageOneLaneA = pWorkSpace->mCelestialLaneA;
    std::uint8_t *aStageOneLaneB = pWorkSpace->mCelestialLaneB;
    std::uint8_t *aStageOneLaneC = pWorkSpace->mCelestialLaneC;
    std::uint8_t *aStageOneLaneD = pWorkSpace->mCelestialLaneD;

    std::uint8_t *aStageTwoLaneA = pWorkSpace->mSpiritLaneA;
    std::uint8_t *aStageTwoLaneB = pWorkSpace->mSpiritLaneB;
    std::uint8_t *aStageTwoLaneC = pWorkSpace->mSpiritLaneC;
    std::uint8_t *aStageTwoLaneD = pWorkSpace->mSpiritLaneD;

    // Fold Stage I — 4 x 16,384 bytes into 4 x 8,192 bytes.

    // Destination A, block 0: source B half 1 block 3 + source C half 1 block 6
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 3U * W_KEY + ((aIndex + 1153U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 6U * W_KEY + ((aIndex + 1108U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 0U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination A, block 1: source C half 1 block 1 + source A half 0 block 0
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 1U * W_KEY + ((aIndex + 1063U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 0U * W_KEY + ((aIndex + 1018U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 1U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination A, block 2: source A half 0 block 3 + source D half 0 block 1
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 3U * W_KEY + ((aIndex + 973U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 1U * W_KEY + ((aIndex + 928U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 2U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination A, block 3: source D half 0 block 4 + source B half 1 block 6
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 4U * W_KEY + ((aIndex + 883U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 6U * W_KEY + ((aIndex + 838U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 3U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination B, block 0: source A half 0 block 6 + source C half 1 block 4
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 6U * W_KEY + ((aIndex + 793U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 4U * W_KEY + ((aIndex + 748U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 0U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination B, block 1: source D half 0 block 7 + source A half 0 block 1
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 7U * W_KEY + ((aIndex + 703U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 1U * W_KEY + ((aIndex + 658U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 1U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination B, block 2: source B half 1 block 1 + source D half 0 block 2
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 1U * W_KEY + ((aIndex + 613U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 2U * W_KEY + ((aIndex + 568U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 2U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination B, block 3: source C half 1 block 7 + source B half 1 block 4
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 7U * W_KEY + ((aIndex + 523U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 4U * W_KEY + ((aIndex + 478U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 3U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination C, block 0: source B half 1 block 7 + source C half 1 block 2
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 7U * W_KEY + ((aIndex + 433U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 2U * W_KEY + ((aIndex + 388U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 0U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination C, block 1: source C half 1 block 5 + source D half 0 block 5
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 5U * W_KEY + ((aIndex + 343U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 5U * W_KEY + ((aIndex + 298U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 1U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination C, block 2: source D half 0 block 0 + source A half 0 block 4
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 0U * W_KEY + ((aIndex + 253U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 4U * W_KEY + ((aIndex + 208U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 2U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination C, block 3: source A half 0 block 7 + source B half 1 block 2
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 7U * W_KEY + ((aIndex + 163U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 2U * W_KEY + ((aIndex + 118U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 3U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination D, block 0: source A half 0 block 2 + source B half 1 block 5
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 2U * W_KEY + ((aIndex + 73U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 5U * W_KEY + ((aIndex + 28U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 0U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination D, block 1: source D half 0 block 3 + source A half 0 block 5
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 3U * W_KEY + ((aIndex + 2031U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 5U * W_KEY + ((aIndex + 1986U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 1U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination D, block 2: source C half 1 block 0 + source D half 0 block 6
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 0U * W_KEY + ((aIndex + 1941U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 6U * W_KEY + ((aIndex + 1896U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 2U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination D, block 3: source B half 1 block 0 + source C half 1 block 3
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 0U * W_KEY + ((aIndex + 1851U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 3U * W_KEY + ((aIndex + 1806U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 3U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Fold Stage II — 4 x 8,192 bytes into 4 x W_KEY bytes.

    // Key piece A
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * (S_HALF >> 1U) + 1U * W_KEY + ((aIndex + 1927U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * (S_HALF >> 1U) + 2U * W_KEY + ((aIndex + 1882U) & W_KEY1);
        const std::size_t aSourceIndexC = 0U * (S_HALF >> 1U) + 3U * W_KEY + ((aIndex + 1837U) & W_KEY1);
        const std::size_t aSourceIndexD = 0U * (S_HALF >> 1U) + 3U * W_KEY + ((aIndex + 1792U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * W_KEY + aIndex;

        std::uint32_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneA[aSourceIndexA]) << 16U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneB[aSourceIndexB]) << 24U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneC[aSourceIndexC]) << 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneD[aSourceIndexD]) << 8U;
        aFoldValue = TwistMix32::DiffuseA(aFoldValue);

        aStageTwoLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Key piece B
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * (S_HALF >> 1U) + 2U * W_KEY + ((aIndex + 1747U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * (S_HALF >> 1U) + 0U * W_KEY + ((aIndex + 1702U) & W_KEY1);
        const std::size_t aSourceIndexC = 0U * (S_HALF >> 1U) + 0U * W_KEY + ((aIndex + 1657U) & W_KEY1);
        const std::size_t aSourceIndexD = 0U * (S_HALF >> 1U) + 2U * W_KEY + ((aIndex + 1612U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * W_KEY + aIndex;

        std::uint32_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneA[aSourceIndexA]) << 24U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneB[aSourceIndexB]) << 16U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneC[aSourceIndexC]) << 8U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneD[aSourceIndexD]) << 0U;
        aFoldValue = TwistMix32::DiffuseA(aFoldValue);

        aStageTwoLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 16U);
    }

    // Key piece C
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * (S_HALF >> 1U) + 0U * W_KEY + ((aIndex + 1567U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * (S_HALF >> 1U) + 3U * W_KEY + ((aIndex + 1522U) & W_KEY1);
        const std::size_t aSourceIndexC = 0U * (S_HALF >> 1U) + 1U * W_KEY + ((aIndex + 1477U) & W_KEY1);
        const std::size_t aSourceIndexD = 0U * (S_HALF >> 1U) + 1U * W_KEY + ((aIndex + 1432U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * W_KEY + aIndex;

        std::uint32_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneA[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneB[aSourceIndexB]) << 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneC[aSourceIndexC]) << 16U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneD[aSourceIndexD]) << 24U;
        aFoldValue = TwistMix32::DiffuseA(aFoldValue);

        aStageTwoLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Key piece D
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * (S_HALF >> 1U) + 3U * W_KEY + ((aIndex + 1387U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * (S_HALF >> 1U) + 1U * W_KEY + ((aIndex + 1342U) & W_KEY1);
        const std::size_t aSourceIndexC = 0U * (S_HALF >> 1U) + 2U * W_KEY + ((aIndex + 1297U) & W_KEY1);
        const std::size_t aSourceIndexD = 0U * (S_HALF >> 1U) + 0U * W_KEY + ((aIndex + 1252U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * W_KEY + aIndex;

        std::uint32_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneA[aSourceIndexA]) << 16U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneB[aSourceIndexB]) << 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneC[aSourceIndexC]) << 24U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneD[aSourceIndexD]) << 8U;
        aFoldValue = TwistMix32::DiffuseA(aFoldValue);

        aStageTwoLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 24U);
    }
}

void TwistExpander_Polaris::TwistForkKeyHalfB(TwistWorkSpace *pWorkSpace) {
    static_assert(S_BLOCK == 32768, "Twist fork source size changed.");
    static_assert(S_HALF == 16384, "Twist fork half size changed.");
    static_assert(W_KEY == 2048, "Twist fork key size changed.");

    std::uint8_t *aSourceLaneA = pWorkSpace->mCrystalLaneA;
    std::uint8_t *aSourceLaneB = pWorkSpace->mCrystalLaneB;
    std::uint8_t *aSourceLaneC = pWorkSpace->mCrystalLaneC;
    std::uint8_t *aSourceLaneD = pWorkSpace->mCrystalLaneD;

    std::uint8_t *aStageOneLaneA = pWorkSpace->mCelestialLaneA;
    std::uint8_t *aStageOneLaneB = pWorkSpace->mCelestialLaneB;
    std::uint8_t *aStageOneLaneC = pWorkSpace->mCelestialLaneC;
    std::uint8_t *aStageOneLaneD = pWorkSpace->mCelestialLaneD;

    std::uint8_t *aStageTwoLaneA = pWorkSpace->mDivinationLaneA;
    std::uint8_t *aStageTwoLaneB = pWorkSpace->mDivinationLaneB;
    std::uint8_t *aStageTwoLaneC = pWorkSpace->mDivinationLaneC;
    std::uint8_t *aStageTwoLaneD = pWorkSpace->mDivinationLaneD;

    // Fold Stage I — 4 x 16,384 bytes into 4 x 8,192 bytes.

    // Destination A, block 0: source A half 1 block 1 + source D half 1 block 2
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 1U * W_KEY + ((aIndex + 1761U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 2U * W_KEY + ((aIndex + 1716U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 0U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination A, block 1: source C half 0 block 7 + source A half 1 block 6
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 7U * W_KEY + ((aIndex + 1671U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 6U * W_KEY + ((aIndex + 1626U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 1U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination A, block 2: source B half 0 block 4 + source C half 0 block 4
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 4U * W_KEY + ((aIndex + 1581U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 4U * W_KEY + ((aIndex + 1536U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 2U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination A, block 3: source D half 1 block 7 + source B half 0 block 1
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 7U * W_KEY + ((aIndex + 1491U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 1U * W_KEY + ((aIndex + 1446U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 3U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination B, block 0: source C half 0 block 1 + source D half 1 block 4
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 1U * W_KEY + ((aIndex + 1401U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 4U * W_KEY + ((aIndex + 1356U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 0U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination B, block 1: source D half 1 block 1 + source A half 1 block 3
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 1U * W_KEY + ((aIndex + 1311U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 3U * W_KEY + ((aIndex + 1266U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 1U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination B, block 2: source A half 1 block 0 + source B half 0 block 6
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 0U * W_KEY + ((aIndex + 1221U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 6U * W_KEY + ((aIndex + 1176U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 2U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination B, block 3: source B half 0 block 3 + source C half 0 block 6
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 3U * W_KEY + ((aIndex + 1131U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 6U * W_KEY + ((aIndex + 1086U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 3U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination C, block 0: source B half 0 block 0 + source C half 0 block 3
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 0U * W_KEY + ((aIndex + 1041U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 3U * W_KEY + ((aIndex + 996U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 0U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination C, block 1: source A half 1 block 5 + source B half 0 block 5
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 5U * W_KEY + ((aIndex + 951U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 5U * W_KEY + ((aIndex + 906U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 1U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination C, block 2: source D half 1 block 6 + source A half 1 block 2
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 6U * W_KEY + ((aIndex + 861U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 2U * W_KEY + ((aIndex + 816U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 2U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination C, block 3: source C half 0 block 0 + source D half 1 block 3
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 0U * W_KEY + ((aIndex + 771U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 3U * W_KEY + ((aIndex + 726U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 3U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination D, block 0: source B half 0 block 2 + source D half 1 block 0
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 2U * W_KEY + ((aIndex + 681U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 0U * W_KEY + ((aIndex + 636U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 0U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination D, block 1: source D half 1 block 5 + source A half 1 block 7
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 5U * W_KEY + ((aIndex + 591U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 7U * W_KEY + ((aIndex + 546U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 1U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination D, block 2: source A half 1 block 4 + source C half 0 block 5
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 4U * W_KEY + ((aIndex + 501U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 5U * W_KEY + ((aIndex + 456U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 2U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination D, block 3: source C half 0 block 2 + source B half 0 block 7
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 2U * W_KEY + ((aIndex + 411U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 7U * W_KEY + ((aIndex + 366U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 3U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Fold Stage II — 4 x 8,192 bytes into 4 x W_KEY bytes.

    // Key piece A
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * (S_HALF >> 1U) + 2U * W_KEY + ((aIndex + 1207U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * (S_HALF >> 1U) + 3U * W_KEY + ((aIndex + 1162U) & W_KEY1);
        const std::size_t aSourceIndexC = 1U * (S_HALF >> 1U) + 0U * W_KEY + ((aIndex + 1117U) & W_KEY1);
        const std::size_t aSourceIndexD = 1U * (S_HALF >> 1U) + 1U * W_KEY + ((aIndex + 1072U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * W_KEY + aIndex;

        std::uint32_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneA[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneB[aSourceIndexB]) << 16U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneC[aSourceIndexC]) << 24U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneD[aSourceIndexD]) << 8U;
        aFoldValue = TwistMix32::DiffuseA(aFoldValue);

        aStageTwoLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 24U);
    }

    // Key piece B
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * (S_HALF >> 1U) + 1U * W_KEY + ((aIndex + 1027U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * (S_HALF >> 1U) + 1U * W_KEY + ((aIndex + 982U) & W_KEY1);
        const std::size_t aSourceIndexC = 1U * (S_HALF >> 1U) + 1U * W_KEY + ((aIndex + 937U) & W_KEY1);
        const std::size_t aSourceIndexD = 1U * (S_HALF >> 1U) + 0U * W_KEY + ((aIndex + 892U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * W_KEY + aIndex;

        std::uint32_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneA[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneB[aSourceIndexB]) << 24U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneC[aSourceIndexC]) << 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneD[aSourceIndexD]) << 16U;
        aFoldValue = TwistMix32::DiffuseA(aFoldValue);

        aStageTwoLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Key piece C
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * (S_HALF >> 1U) + 3U * W_KEY + ((aIndex + 847U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * (S_HALF >> 1U) + 0U * W_KEY + ((aIndex + 802U) & W_KEY1);
        const std::size_t aSourceIndexC = 1U * (S_HALF >> 1U) + 3U * W_KEY + ((aIndex + 757U) & W_KEY1);
        const std::size_t aSourceIndexD = 1U * (S_HALF >> 1U) + 2U * W_KEY + ((aIndex + 712U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * W_KEY + aIndex;

        std::uint32_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneA[aSourceIndexA]) << 16U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneB[aSourceIndexB]) << 24U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneC[aSourceIndexC]) << 8U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneD[aSourceIndexD]) << 0U;
        aFoldValue = TwistMix32::DiffuseA(aFoldValue);

        aStageTwoLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 16U);
    }

    // Key piece D
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * (S_HALF >> 1U) + 0U * W_KEY + ((aIndex + 667U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * (S_HALF >> 1U) + 2U * W_KEY + ((aIndex + 622U) & W_KEY1);
        const std::size_t aSourceIndexC = 1U * (S_HALF >> 1U) + 2U * W_KEY + ((aIndex + 577U) & W_KEY1);
        const std::size_t aSourceIndexD = 1U * (S_HALF >> 1U) + 3U * W_KEY + ((aIndex + 532U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * W_KEY + aIndex;

        std::uint32_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneA[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneB[aSourceIndexB]) << 8U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneC[aSourceIndexC]) << 16U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneD[aSourceIndexD]) << 24U;
        aFoldValue = TwistMix32::DiffuseA(aFoldValue);

        aStageTwoLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }
}

